import { encodeUtf8AsBase64Url } from './base64url.mjs';
import { signHmacSha256 } from './signature.mjs';

function encodeJsonSegment(value) {
  return encodeUtf8AsBase64Url(JSON.stringify(value));
}

export async function encodeJwt(payload, secret) {
  const headerSegment = encodeJsonSegment({ alg: 'HS256', typ: 'JWT' });
  const payloadSegment = encodeJsonSegment(payload);
  const signingInput = `${headerSegment}.${payloadSegment}`;
  const signatureSegment = await signHmacSha256(signingInput, secret);

  return `${signingInput}.${signatureSegment}`;
}

